import csv, json, hashlib, re, sys, statistics as st
from collections import Counter
D = sys.argv[1]
def load(n):
    with open(f"{D}/{n}", newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))
tr, va = load("train.csv"), load("validation.csv")
m = json.load(open(f"{D}/manifest.json"))
print("files:", json.dumps(m["files"], indent=1)[:1500])
for n in ["train.csv", "validation.csv"]:
    print(n, hashlib.sha256(open(f"{D}/{n}", "rb").read()).hexdigest())
print("cols", list(tr[0].keys()))
for name, d in [("train", tr), ("val", va)]:
    c = Counter(r["label"] for r in d)
    print(name, len(d), c)
    for lab in ["spam", "ham"]:
        L = [len(r["text"]) for r in d if r["label"] == lab]
        W = [len(r["text"].split()) for r in d if r["label"] == lab]
        print(f"  {lab}: chars med={st.median(L)} min={min(L)} max={max(L)} | words med={st.median(W)}")
    print("  empty/short(<50):", sum(len(r["text"].strip()) < 50 for r in d))
# manifest consistency
mm = {x["message_id"]: x for x in m["messages"]}
src2lab = {"easy_ham": "ham", "spam": "spam"}
bad = [r["message_id"] for r in tr + va if r["message_id"] not in mm or mm[r["message_id"]]["split"] != ("train" if r in tr else "validation") or src2lab[mm[r["message_id"]]["source"]] != r["label"]]
print("manifest mismatches:", len(bad), "manifest msgs", len(m["messages"]))
print("id overlap:", len({r['message_id'] for r in tr} & {r['message_id'] for r in va}))
# duplicates / near-dups
norm = lambda t: re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 ]", " ", t.lower())).strip()
nt = {norm(r["text"]) for r in tr}
print("exact norm dup val-in-train:", sum(norm(r["text"]) in nt for r in va))
def sh(t, k=5):
    w = norm(t).split(); return {" ".join(w[i:i+k]) for i in range(max(1, len(w)-k+1))}
S = [(r, sh(r["text"])) for r in tr]
near = []
for v in va:
    sv = sh(v["text"])
    best = max(((len(sv & s) / len(sv | s), r) for r, s in S), key=lambda x: x[0])
    if best[0] > 0.3: near.append((round(best[0], 2), v["message_id"], v["label"], best[1]["message_id"], best[1]["label"]))
print("val near-dups of train (jaccard>0.3):", sorted(near, reverse=True))
nd_tr = []
for i in range(len(S)):
    for j in range(i+1, len(S)):
        a, b = S[i][1], S[j][1]; jac = len(a & b) / len(a | b)
        if jac > 0.5: nd_tr.append((round(jac, 2), S[i][0]["label"], S[j][0]["label"]))
print("train-train near dup pairs >0.5:", nd_tr)
# subject line / structure
for name, d in [("train", tr), ("val", va)]:
    print(name, "first-line starts:", Counter(r["text"].split("\n", 1)[0][:9] for r in d).most_common(5))
# surface features by label
feats = {
 "url": r"https?://|www\.", "html": r"<\s*(html|body|table|font|a |br|p>)", "dollar": r"\$\d", "exclam!!": r"!!",
 "CAPS word": r"\b[A-Z]{5,}\b", "unsubscribe": r"unsubscribe|remove", "free": r"\bfree\b", "email addr": r"\S+@\S+",
 "quote '>'": r"(?m)^>", "click": r"click", "mojibake": r"[ÃÂ�]", "non-ascii": r"[^\x00-\x7f]",
 "list footer": r"mailing list|listinfo|_______________", "spamassassin": r"spamassassin",
}
tot = Counter(r["label"] for r in tr)
print("\nfeature rate in train (spam / ham):")
for k, p in feats.items():
    c = Counter(r["label"] for r in tr if re.search(p, r["text"], re.I if k not in ("CAPS word",) else 0))
    print(f"  {k:14s} {c['spam']/tot['spam']:.2f} / {c['ham']/tot['ham']:.2f}")
# top discriminative tokens (log-odds w/ smoothing)
import math
tok = lambda t: set(re.findall(r"[a-z][a-z']{2,}", t.lower()))
df = {"spam": Counter(), "ham": Counter()}
for r in tr: df[r["label"]].update(tok(r["text"]))
vocab = set(df["spam"]) | set(df["ham"])
print("vocab size (train, doc-set):", len(vocab))
lo = {w: math.log((df["spam"][w]+1)/(tot["spam"]+2)) - math.log((df["ham"][w]+1)/(tot["ham"]+2)) for w in vocab if df["spam"][w]+df["ham"][w] >= 5}
s = sorted(lo.items(), key=lambda x: x[1])
print("top ham:", [(w, df['spam'][w], df['ham'][w]) for w, _ in s[:25]])
print("top spam:", [(w, df['spam'][w], df['ham'][w]) for w, _ in s[-25:]])
vt = set().union(*(tok(r["text"]) for r in va))
print("val vocab OOV share:", round(len(vt - vocab) / len(vt), 2))

