# Quick feasibility probe: Multinomial NB (stdlib) with stratified 5-fold CV on TRAIN only. Validation untouched.
import csv, re, sys, math, random
from collections import Counter
D=sys.argv[1]
tr=list(csv.DictReader(open(f"{D}/train.csv",newline="",encoding="utf-8")))
ART=[r"zzzz\S*",r"spamassassin\.taint\.org",r"\[[A-Za-z]+\]",r"(?s)_{10,}.*$",r"newsisfree\S*",r"(?m)^(URL|Date): .*$",r"\S+@\S+",r"https?://\S+"]
def tok(t,clean):
    if clean:
        for p in ART: t=re.sub(p," ",t,flags=re.I)
    return re.findall(r"[a-z][a-z']+|\$\d+|!+",t.lower())
def run(clean,seed=0):
    random.seed(seed)
    idx={l:[i for i,r in enumerate(tr) if r["label"]==l] for l in ("spam","ham")}
    for l in idx: random.shuffle(idx[l])
    folds=[[] for _ in range(5)]
    for l in idx:
        for k,i in enumerate(idx[l]): folds[k%5].append(i)
    tp=fp=fn=tn=0
    for f in folds:
        trn=[tr[i] for i in range(len(tr)) if i not in f]
        cnt={"spam":Counter(),"ham":Counter()}; nd=Counter(r["label"] for r in trn)
        for r in trn: cnt[r["label"]].update(tok(r["text"],clean))
        V=set(cnt["spam"])|set(cnt["ham"]); T={l:sum(cnt[l].values()) for l in cnt}
        for i in f:
            w=tok(tr[i]["text"],clean)
            sc={l:math.log(nd[l]/len(trn))+sum(math.log((cnt[l][x]+1)/(T[l]+len(V))) for x in w if x in V) for l in cnt}
            p="spam" if sc["spam"]>sc["ham"] else "ham"; y=tr[i]["label"]
            tp+=p==y=="spam"; tn+=p==y=="ham"; fp+=(p=="spam" and y=="ham"); fn+=(p=="ham" and y=="spam")
    return tp,fp,fn,tn
