    res=[run(clean,s) for s in range(5)]
    tp,fp,fn,tn=[sum(x[k] for x in res)/5 for k in range(4)]
    print(f"clean={clean}: TP={tp} FP={fp} FN={fn} TN={tn} | precision={tp/(tp+fp):.3f} recall={tp/(tp+fn):.3f} acc={(tp+tn)/180:.3f}")
EOF
